alter table public.skills add column if not exists skill_rank text;
alter table public.skills add column if not exists skill_scope text not null default 'CLASS';
alter table public.skills add column if not exists proof_type text not null default 'PERFORMANCE';
alter table public.skills add column if not exists mastery_requirements jsonb not null default '{}'::jsonb;

alter table public.skills drop constraint if exists skills_skill_rank_check;
alter table public.skills add constraint skills_skill_rank_check check (skill_rank is null or skill_rank = any (array['E','D','C','B','A','S']));
alter table public.skills drop constraint if exists skills_skill_scope_check;
alter table public.skills add constraint skills_skill_scope_check check (skill_scope = any (array['UNIVERSAL','CLASS','CROSS_CLASS']));
alter table public.skills drop constraint if exists skills_proof_type_check;
alter table public.skills add constraint skills_proof_type_check check (proof_type = any (array['PERFORMANCE','LEARNING','PROJECT','LEADERSHIP','ENDURANCE','EXECUTION','HABIT','MIXED']));

update public.skills
set skill_rank = case
  when unlock_level <= 5 then 'E'
  when unlock_level <= 15 then 'D'
  when unlock_level <= 30 then 'C'
  when unlock_level <= 45 then 'B'
  when unlock_level <= 60 then 'A'
  else 'S'
end
where skill_rank is null;

update public.skills set proof_type = 'LEARNING' where class_affinity = array['MAGE']::text[] or primary_attribute = 'INTELLIGENCE';
update public.skills set proof_type = 'ENDURANCE' where class_affinity = array['RANGER']::text[] and progression_group in ('RUNNING','ENDURANCE');
update public.skills set proof_type = 'LEADERSHIP' where class_affinity = array['COMMANDER']::text[] and progression_group = 'DISCIPLINE';
update public.skills set proof_type = 'EXECUTION' where class_affinity = array['ASSASSIN']::text[] and primary_attribute in ('SPEED','FOCUS');

create table if not exists public.learning_records (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  skill_id bigint references public.skills(id) on delete set null,
  title text not null check (char_length(title) between 1 and 180),
  source_title text not null check (char_length(source_title) between 1 and 240),
  source_type text not null default 'TOPIC' check (source_type = any (array['BOOK','COURSE','ARTICLE','VIDEO','TOPIC','CLASS','OTHER'])),
  duration_minutes integer not null check (duration_minutes > 0),
  learning_summary text not null check (char_length(learning_summary) >= 20),
  key_takeaways jsonb not null default '[]'::jsonb,
  application_plan text,
  mastery_evidence jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

alter table public.learning_records enable row level security;
grant select, insert, update, delete on public.learning_records to authenticated;
grant usage, select on sequence public.learning_records_id_seq to authenticated;

drop policy if exists learning_records_select_own on public.learning_records;
create policy learning_records_select_own on public.learning_records for select to authenticated using ((select auth.uid()) = user_id);
drop policy if exists learning_records_insert_own on public.learning_records;
create policy learning_records_insert_own on public.learning_records for insert to authenticated with check ((select auth.uid()) = user_id);
drop policy if exists learning_records_update_own on public.learning_records;
create policy learning_records_update_own on public.learning_records for update to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
drop policy if exists learning_records_delete_own on public.learning_records;
create policy learning_records_delete_own on public.learning_records for delete to authenticated using ((select auth.uid()) = user_id);
create index if not exists learning_records_user_id_idx on public.learning_records(user_id);
create index if not exists learning_records_skill_id_idx on public.learning_records(skill_id);
create index if not exists skills_rank_class_idx on public.skills(skill_rank, skill_scope);

