insert into public.skill_prerequisites(skill_id, prerequisite_skill_id, minimum_status)
select s.id,p.id,'MASTERED' from links l join public.skills s on s.slug=l.skill_slug join public.skills p on p.slug=l.prereq_slug
on conflict (skill_id, prerequisite_skill_id) do update set minimum_status='MASTERED';
